#ifndef FITS_IN_8_BITS
#define FITS_IN_8_BITS(c) (sizeof(c) == 1 || ((UV)(c) & ~(UV)0xFF) == 0)
#endif
#define CC_mask_(classnum) (1U << (classnum))
#define CC_mask_A_(classnum) (CC_mask_(classnum) | CC_mask_(CC_ASCII_))
#define generic_isCC_(c, classnum) \
    cBOOL(FITS_IN_8_BITS(c) && (PL_charclass[(U8)(c)] & CC_mask_(classnum)))
#define generic_isCC_A_(c, classnum)                                       \
    (FITS_IN_8_BITS(c) &&                                                  \
     ((PL_charclass[(U8)(c)] & CC_mask_A_(classnum)) == CC_mask_A_(classnum)))

