/* Case changes of one byte (handy.h). */
#ifndef toLOWER_A
#define toLOWER_A(c) (isUPPER_A(c) ? (U8)((c) + ('a' - 'A')) : (c))
#endif
#ifndef toUPPER_A
#define toUPPER_A(c) (isLOWER_A(c) ? (U8)((c) - ('a' - 'A')) : (c))
#endif
#ifndef toFOLD_A
#define toFOLD_A(c) toLOWER_A(c)
#endif
#ifndef toTITLE_A
#define toTITLE_A(c) toUPPER_A(c)
#endif
#ifndef toLOWER_L1
#define toLOWER_L1(c) (FITS_IN_8_BITS(c) ? (U8)PL_latin1_lc[(U8)(c)] : (U8)(c))
#endif
